package com.agentic.shortener.service;

import com.google.zxing.BarcodeFormat;
import com.google.zxing.EncodeHintType;
import com.google.zxing.WriterException;
import com.google.zxing.common.BitMatrix;
import com.google.zxing.qrcode.QRCodeWriter;
import com.google.zxing.qrcode.decoder.ErrorCorrectionLevel;
import org.springframework.stereotype.Service;

import javax.imageio.ImageIO;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.util.Map;

/** Renders QR codes in-process (no network calls). The output is deterministic for the same input. */
@Service
public class QrCodeService {

    public static final int MIN_SIZE = 64;
    public static final int MAX_SIZE = 1024;
    public static final int DEFAULT_SIZE = 256;

    private static final Map<EncodeHintType, Object> HINTS = Map.of(
            EncodeHintType.ERROR_CORRECTION, ErrorCorrectionLevel.M,
            EncodeHintType.MARGIN, 1,
            EncodeHintType.CHARACTER_SET, "UTF-8");

    /** A black-and-white PNG that is exactly {@code size} pixels wide and high. */
    public byte[] png(String content, int size) {
        requireValidSize(size);
        BitMatrix matrix = encode(content, size, size);
        BufferedImage image = new BufferedImage(matrix.getWidth(), matrix.getHeight(), BufferedImage.TYPE_BYTE_BINARY);
        for (int x = 0; x < matrix.getWidth(); x++) {
            for (int y = 0; y < matrix.getHeight(); y++) {
                image.setRGB(x, y, matrix.get(x, y) ? 0xFF000000 : 0xFFFFFFFF);
            }
        }
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        try {
            ImageIO.write(image, "png", out);
        } catch (IOException e) {
            throw new IllegalStateException("Could not encode the QR code as PNG", e);
        }
        return out.toByteArray();
    }

    /** A vector QR code, one path for all dark modules, scaled to {@code size} pixels. */
    public String svg(String content, int size) {
        requireValidSize(size);
        BitMatrix matrix = encode(content, 0, 0);
        int modules = matrix.getWidth();
        StringBuilder path = new StringBuilder();
        for (int y = 0; y < modules; y++) {
            for (int x = 0; x < modules; x++) {
                if (matrix.get(x, y)) {
                    path.append('M').append(x).append(' ').append(y).append("h1v1h-1z");
                }
            }
        }
        return "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 " + modules + ' ' + modules + "\" width=\"" + size
                + "\" height=\"" + size + "\" shape-rendering=\"crispEdges\"><rect width=\"" + modules + "\" height=\""
                + modules + "\" fill=\"#fff\"/><path d=\"" + path + "\" fill=\"#000\"/></svg>";
    }

    public static void requireValidSize(int size) {
        if (size < MIN_SIZE || size > MAX_SIZE) {
            throw new IllegalArgumentException("size must be between " + MIN_SIZE + " and " + MAX_SIZE + " pixels");
        }
    }

    private BitMatrix encode(String content, int width, int height) {
        if (content == null || content.isBlank()) {
            throw new IllegalArgumentException("content is required");
        }
        try {
            return new QRCodeWriter().encode(content, BarcodeFormat.QR_CODE, width, height, HINTS);
        } catch (WriterException e) {
            throw new IllegalStateException("Could not encode the QR code", e);
        }
    }
}
